mapper.sql:
WHERE
		M.STATUS_CODE IN (9, 2)



	AND M.LOCGOV_CODE = (SELECT LOCGOV_CODE FROM OP_MANAGER WHERE USER_ID = #{loginUserId})




	AND M.BANK_CODE = (SELECT BANK_CODE FROM OP_MANAGER WHERE USER_ID = #{loginUserId})






			AND CONCAT(L.UPPER_LOCGOV_NM, ' ', L.LOCGOV_NM) LIKE CONCAT('%', #{srchValue},'%')


			AND M.LOGIN_ID = #{srchValue}


			AND M.USER_NAME = #{srchValue}


			AND M.PHONE_NUMBER = #{srchValue}


			AND M.PSITN_NM LIKE CONCAT('%', #{srchValue},'%')


			AND M.EMP_ID = #{srchValue}






	AND DATE_FORMAT(M.CREATED_DATE,'%Y%m%d')  >=  #{srchStartCreated}




	AND DATE_FORMAT(M.CREATED_DATE,'%Y%m%d')  <=  #{srchEndCreated}




	AND M.STATUS_CODE = #{srchStatusCode}




	AND R.AUTHORITY IN (

			#{item}

	)

mapper.select:
/** psersonincharge-mapper.getChargerCountByParam (담당자 관리 목록 갯수 조회 ) */ SELECT COUNT(*) FROM OP_MANAGER M INNER JOIN OP_USER_ROLE R ON R.USER_ID = M.USER_ID AND R.AUTHORITY IN (
#{item}
''
)

/** psersonincharge-mapper.getChargerListByParam (담당자 관리 목록 조회) */ SELECT A.LOCGOV_CODE , B.LOCGOV_NM , B.UPPER_LOCGOV_CODE , B.UPPER_LOCGOV_NM , A.AUTHORITY , A.LOGIN_ID AS LOGIN_ID , A.USER_NAME AS USER_NAME , A.PHONE_NUMBER AS PHONE_NUMBER , DATE_FORMAT(A.CREATED_DATE,'%Y-%m-%d') AS CREATED_DATE , A.STATUS_CODE , DATE_FORMAT(A.DENY_DATE,'%Y-%m-%d') AS DENY_DATE , A.USER_ID , A.PSITN_DEPT_NM , A.BANK_CODE , A.PSITN_NM , A.EMP_ID AS EMP_ID , A.BANK_NM FROM (
SELECT M.LOCGOV_CODE , R.AUTHORITY , M.LOGIN_ID , M.USER_NAME , M.PHONE_NUMBER , M.CREATED_DATE , M.STATUS_CODE , M.DENY_DATE , M.USER_ID , M.PSITN_DEPT_NM , M.BANK_CODE , M.PSITN_NM , M.EMP_ID , ( SELECT C.LABEL FROM OP_COMMON_CODE C WHERE C.CODE_TYPE = 'OFF_BANK_LIST' AND C.USE_YN = 'Y' AND C.LANGUAGE = 'ko' AND C.ID = M.BANK_CODE) AS BANK_NM FROM OP_MANAGER M INNER JOIN OP_USER_ROLE R ON R.USER_ID = M.USER_ID AND R.AUTHORITY IN (
#{item}
''
)
ORDER BY BANK_NM, M.PSITN_NM
ORDER BY M.CREATED_DATE DESC
) A LEFT OUTER JOIN G_LOCGOV B ON A.LOCGOV_CODE = B.LOCGOV_CODE

