mapper.select:
/** psersonincharge-mapper.getChargerDetails (담당자 상세 조회) */ SELECT L.LOCGOV_CODE , L.LOCGOV_NM , L.UPPER_LOCGOV_CODE , L.UPPER_LOCGOV_NM , R.AUTHORITY , M.LOGIN_ID AS LOGIN_ID , M.USER_NAME AS USER_NAME , M.PHONE_NUMBER AS PHONE_NUMBER , DATE_FORMAT(M.CREATED_DATE,'%Y-%m-%d') AS CREATED_DATE , M.STATUS_CODE , DATE_FORMAT(M.DENY_DATE,'%Y-%m-%d') AS DENY_DATE , M.USER_ID , M.BANK_CODE , M.EMP_ID AS EMP_ID , M.PSITN_NM , M.PSITN_DEPT_NM , M.OFCPS_NM AS OFCPS_NM , M.EMAIL AS EMAIL , ( SELECT C.LABEL FROM OP_COMMON_CODE C WHERE C.CODE_TYPE = 'OFF_BANK_LIST' AND C.USE_YN = 'Y' AND C.LANGUAGE = 'ko' AND C.ID = M.BANK_CODE) AS BANK_NM FROM OP_MANAGER M INNER JOIN OP_USER_ROLE R ON R.USER_ID = M.USER_ID AND R.AUTHORITY IN (
#{item}
''
) LEFT OUTER JOIN G_LOCGOV L ON L.LOCGOV_CODE = M.LOCGOV_CODE WHERE M.STATUS_CODE IN (9, 2) AND M.USER_ID = #{userId}

