/** personincharge-mapper.updateUserDetailOffPersonTel (오프라인 담당자 지점 연락처는 DsgnCntrManagerRequest.java의 phoneNumber에 지점 연락처 들어있음) */
UPDATE	OP_USER_DETAIL
SET		TEL_NUMBER = #{phoneNumber}
WHERE	USER_ID = #{userId}

/** personincharge-mapper.updateOffPersonInCharge (오프라인 담당자 수정) */ UPDATE OP_MANAGER SET USER_NAME = #{userName}, PHONE_NUMBER = #{phoneNumber}, BANK_CODE = #{bankCode}, PSITN_NM = #{psitnNm}, EMP_ID = #{empId}, EMAIL = #{email}, OFCPS_NM = #{email}, INFO_UPDT_DE = ( SELECT CASE WHEN IFNULL(INFO_UPDT_DE, '') != '' THEN INFO_UPDT_DE ELSE END FROM OP_MANAGER WHERE USER_ID = #{userId}),
STATUS_CODE = #{statusCode},
DENY_DATE = ,
DENY_DATE = NULL,
UPDATED_DATE = WHERE USER_ID = #{userId}

mapper.select:
