/** personincharge-mapper.updateUserSync (회원 정보 수정) */
UPDATE	OP_USER
SET		USER_NAME = (SELECT USER_NAME FROM OP_MANAGER WHERE USER_ID = #{userId})
		, EMAIL = (SELECT EMAIL FROM OP_MANAGER WHERE USER_ID = #{userId})
WHERE	USER_ID = #{userId}

/** personincharge-mapper.updateUserDetailSync (회원 상세 정보 수정) */
UPDATE	OP_USER_DETAIL
SET		PHONE_NUMBER = (SELECT PHONE_NUMBER FROM OP_MANAGER WHERE USER_ID = #{userId})

			,TEL_NUMBER = #{telNumber}

WHERE	USER_ID = #{userId}

mapper.select:
/** personincharge-mapper.getManagerInfoUpdateDate (관리자 정보갱신일자 조회) */
SELECT IFNULL(M.INFO_UPDT_DE, '') AS INFO_UPDT_DE
FROM OP_MANAGER M
WHERE M.USER_ID = #{userId}
AND M.STATUS_CODE = 9

/** personincharge-mapper.getUserAdminRole (사용자 관리자 권한 조회) */
SELECT R.AUTHORITY
FROM OP_USER_ROLE R
WHERE R.USER_ID = #{userId}
AND R.AUTHORITY LIKE 'ROLE_ADMIN_%'
LIMIT 1

